import{j as e}from"./index-Q5tmBBoz.js";import{I as t}from"./InfoPage-CouG5ON_.js";import"./PageHeader-D19aNveu.js";function i(){return e.jsx(t,{title:"Sport at Brightwell",lead:"From the inter-college leagues to international representation, sport is part of everyday life at Brightwell — and everyone, of every ability, is welcome to take part.",crumbs:[{to:"/",label:"Home"},{to:"/events",label:"Events"},{label:"Sport"}],sections:[{heading:"A sporting community",body:["Most colleges field teams in more than eighty sports, from football and athletics to fencing and rowing. The inter-college leagues are fiercely contested and draw some of the largest crowds on campus.","The University Sports Centre is the home of performance sport, with pools, courts, a climbing wall and a fully equipped strength and conditioning suite open to all members."],aside:{title:"Facilities",rows:[["Sports centre","Open 06:30 – 22:30"],["Playing fields","120 acres"],["Sports clubs","82"],["Membership","Free for students"]],links:[["/student-life","Student life"]]}},{heading:"Performance and support",body:["Brightwell’s most talented athletes are supported through the Performance Sport programme, combining coaching, sports science and flexible academic arrangements agreed with their tutors.","Representative teams compete nationally and internationally, and the annual Varsity match against our great rival is the highlight of the sporting calendar."],list:{title:"Ways to get involved",items:["Join a club society — most run taster sessions in the first two weeks of term.","Try a beginners’ course in rowing, climbing or athletics through the sports centre.","Volunteer as a coach, official or event steward.","Represent your college even if you have never represented anyone before."]}},{heading:"Wellbeing through sport",body:["Sport is as much about wellbeing as competition. The University funds a network of mental-health-aware club volunteers, and offers subsidised social sessions for staff and students who want to stay active without the matchday pressure."],aside:{title:"Find out more",rows:[["Book courts","sports@brightwell.ng"],["Club directory","82 active club pages"],["Fixture lists","Updated weekly"]],links:[["/events","What’s on"],["/student-life","Clubs and societies"]]}}]})}export{i as default};
